messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Red vs Blue: Three.js Race</title>
    <style>
        html, body {
            width: 100%;
            height: 100%;
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB; /* Sky blue fallback */
        }
        canvas {
            display: block;
        }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB); // Sky blue
scene.fog = new THREE.Fog(0x87CEEB, 100, 900);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 2000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
dirLight.position.set(150, 300, 200);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
scene.add(dirLight);

// --- Ground & Finish Line ---
const groundGeo = new THREE.BoxGeometry(2000, 10, 200);
const groundMat = new THREE.MeshLambertMaterial({ color: 0x44aa44 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.position.y = -5;
ground.receiveShadow = true;
scene.add(ground);

const finishGeo = new THREE.PlaneGeometry(20, 4);
const finishMat = new THREE.MeshLambertMaterial({ color: 0xffffff });
const finishLine = new THREE.Mesh(finishGeo, finishMat);
finishLine.rotation.x = -Math.PI / 2;
finishLine.position.set(700, 0.1, 0);
scene.add(finishLine);

// --- Car Helpers ---
function createCarMesh(color, type) {
    const carGroup = new THREE.Group();
    const chassisGeo = new THREE.BoxGeometry(4, 1.5, 8);
    const chassisMat = new THREE.MeshLambertMaterial({ color: color });
    const chassis = new THREE.Mesh(chassisGeo, chassisMat);
    chassis.position.y = 1.25;
    chassis.castShadow = true;
    carGroup.add(chassis);

    const cabinGeo = new THREE.BoxGeometry(3, 1.2, 4);
    const cabinMat = new THREE.MeshLambertMaterial({ color: 0x333333 });
    const cabin = new THREE.Mesh(cabinGeo, cabinMat);
    cabin.position.set(0, 2.4, 0.6);
    cabin.castShadow = true;
    carGroup.add(cabin);

    const wheelGeo = new THREE.CylinderGeometry(0.8, 0.8, 0.5, 24);
    const wheelMat = new THREE.MeshLambertMaterial({ color: 0x111111 });
    const wheelPositions = [
        [-1.8, 0.8, 3.2], [1.8, 0.8, 3.2],
        [-1.8, 0.8, -3.2], [1.8, 0.8, -3.2]
    ];
    wheelPositions.forEach(pos => {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        carGroup.add(wheel);
    });

    // Add a simple spoiler for visual flair
    const spoilerGeo = new THREE.BoxGeometry(0.4, 0.2, 2.2);
    const spoilerMat = new THREE.MeshLambertMaterial({ color: color });
    const spoiler = new THREE.Mesh(spoilerGeo, spoilerMat);
    spoiler.position.set(0, 2.8, -3.8);
    carGroup.add(spoiler);

    return carGroup;
}

// --- Race State ---
const trackLength = 1400;
const finishLineZ = 700;
const startPos = -trackLength / 2;
const startOffset = 20; // Distance between cars at start
const laneOffset = 25; // Lateral separation

let raceProgress = 0; // 0 to 1 over one full lap
let resetTimer = 0;

const blueCar = createCarMesh(0x0000ff, 'blue');
const redCar = createCarMesh(0xff0000, 'red');
scene.add(blueCar, redCar);

// Initial positions (blue leads)
blueCar.position.set(startPos + startOffset, 0, startPos);
redCar.position.set(startPos, 0, startPos);

// --- Animation Loop ---
function animate() {
    requestAnimationFrame(animate);

    const speed = 120;
    const acceleration = 1.0; // Red car gains speed over time

    // Blue car: constant speed
    blueCar.position.z += speed * 0.01;
    // Red car: accelerates
    redCar.position.z += speed * 0.01 * (1 + acceleration * raceProgress);

    // Camera follows the lead car (blue initially, then red)
    const leadCar = blueCar.position.z > redCar.position.z ? blueCar : redCar;
    const camZ = leadCar.position.z + 200;
    const camX = (leadCar.position.x - redCar.position.x) * 0.1;
    camera.position.set(camX, camZ - 120, 150);
    camera.lookAt(leadCar.position.x, leadCar.position.y - 30, leadCar.position.z);

    // Progress calculation
    const relativePos = blueCar.position.z - redCar.position.z;
    const totalDistance = trackLength;
    raceProgress = Math.max(0, Math.min(1, (relativePos - startPos) / totalDistance));

    // Visual feedback: particles when overtaking
    if (relativePos < startOffset && relativePos > -startOffset) {
        resetTimer = 0;
    }
    if (resetTimer > 0) {
        resetTimer--;
    }

    // Reset after red wins
    if (raceProgress > 0.99 && resetTimer === 0) {
        blueCar.position.set(startPos + startOffset, 0, startPos);
        redCar.position.set(startPos, 0, startPos);
        raceProgress = 0;
    }

    renderer.render(scene, camera);
}

// Resize handler
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

animate();
</script>
</body>
</html>
```
